create table if not exists public.xyock_review_admins(user_id uuid primary key references auth.users(id) on delete cascade,created_at timestamptz not null default now());
create table if not exists public.xyock_review_feedback(id uuid primary key default gen_random_uuid(),answer_id text not null check(char_length(answer_id) between 1 and 180),source_site text not null check(char_length(source_site) between 1 and 255),feedback_type text not null check(feedback_type in ('up','down','clear','report')),category text check(category is null or category in ('incorrect','unsafe','harassment','privacy','spam','other')),reason text not null default '' check(char_length(reason)<=1500),answer_excerpt text not null default '' check(char_length(answer_excerpt)<=4000),page_url text not null default '' check(char_length(page_url)<=2048),visitor_id text not null check(char_length(visitor_id) between 8 and 100),created_at timestamptz not null default now());
create index if not exists xyock_review_feedback_created_at_idx on public.xyock_review_feedback(created_at desc);
create index if not exists xyock_review_feedback_answer_idx on public.xyock_review_feedback(source_site,answer_id,created_at desc);
create index if not exists xyock_review_feedback_type_idx on public.xyock_review_feedback(feedback_type,created_at desc);
alter table public.xyock_review_admins enable row level security;alter table public.xyock_review_feedback enable row level security;
revoke all privileges on table public.xyock_review_admins from public,anon,authenticated;revoke all privileges on table public.xyock_review_feedback from public,anon,authenticated;
grant select,insert,update,delete on table public.xyock_review_admins to service_role;grant select,insert,update,delete on table public.xyock_review_feedback to service_role;
insert into public.xyock_review_admins(user_id) select id from public.profiles where id='dfcbdfb9-2b00-412e-bf43-73bd9a7ba82a'::uuid on conflict(user_id) do nothing;